#ifndef TIMER_H_
#define TIMER_H_

#include <stdint.h>
#include <stdbool.h>

/* Khởi tạo Timer0 (1 kHz CTC) và Timer2 (50 kHz CTC) */
void timer_init(void);

/* Trả về số ms hệ thống từ khi khởi động */
uint32_t timer_get_ms(void);

/* Kiểm tra và xoá cờ chu kỳ vòng cân bằng 4 ms (Tầng 2) */
bool timer_check_control_flag(void);

#endif /* TIMER_H_ */

#include "timer.h"
#include "config.h"
#include <avr/interrupt.h>

static volatile uint32_t s_system_ms = 0;
static volatile bool s_flag_control_4ms = false;
static volatile uint8_t s_tick_counter_4ms = 0;

/* Khai báo hàm ngắt tầng 1 sinh xung bước từ mô-đun motor */
extern void motor_isr_step(void);

void timer_init(void) {
    /* -------------------------------------------------------------------------
     * Cấu hình Timer0: Chế độ CTC, Prescaler 64
     * 16 MHz / 64 = 250 kHz -> OCR0A = 249 tạo ngắt chu kỳ đúng 1 ms (1000 Hz)
     * (anh cho, chưa có tài liệu)
     * ------------------------------------------------------------------------- */
    TCCR0A = (1 << WGM01);              /* CTC mode */
    TCCR0B = (1 << CS01) | (1 << CS00); /* Prescaler 64 */
    OCR0A  = 249;
    TIMSK0 |= (1 << OCIE0A);            /* Bật ngắt so sánh kênh A */

    /* -------------------------------------------------------------------------
     * Cấu hình Timer2: Chế độ CTC, Prescaler 8
     * 16 MHz / 8 = 2 MHz -> OCR2A = 39 tạo ngắt chu kỳ đúng 20 µs (50000 Hz)
     * (anh cho, chưa có tài liệu)
     * ------------------------------------------------------------------------- */
    TCCR2A = (1 << WGM21);              /* CTC mode */
    TCCR2B = (1 << CS21);               /* Prescaler 8 */
    OCR2A  = 39;
    TIMSK2 |= (1 << OCIE2A);            /* Bật ngắt so sánh kênh A */
}

/* Ngắt Timer0: 1 ms hệ thống, đánh cờ kích hoạt Tầng 2 mỗi 4 ms */
ISR(TIMER0_COMPA_vect) {
    s_system_ms++;
    s_tick_counter_4ms++;
    if (s_tick_counter_4ms >= CONTROL_LOOP_MS) {
        s_tick_counter_4ms = 0;
        s_flag_control_4ms = true;
    }
}

/* Ngắt Timer2: Tầng 1 sinh xung bước (50 kHz, chu kỳ 20 µs) */
ISR(TIMER2_COMPA_vect) {
    motor_isr_step();
}

uint32_t timer_get_ms(void) {
    uint32_t ms;
    uint8_t sreg = SREG;
    cli(); /* Cấm ngắt ngắn gọn (< 0.5 µs, tuân thủ NFR-02) */
    ms = s_system_ms;
    SREG = sreg;
    return ms;
}

bool timer_check_control_flag(void) {
    if (s_flag_control_4ms) {
        s_flag_control_4ms = false;
        return true;
    }
    return false;
}

#include "timer.h"
#include "config.h"
#include <avr/interrupt.h>

static volatile uint32_t s_system_ms = 0;
static volatile bool s_flag_control_4ms = false;
static volatile uint8_t s_tick_counter_4ms = 0;

/* Khai báo hàm ngắt tầng 1 sinh xung bước từ mô-đun motor */
extern void motor_isr_step(void);

void timer_init(void) {
    /* Cấu hình Timer0: Chế độ CTC, Prescaler 64, ngắt chu kỳ 1 ms */
    TCCR0A = (1 << WGM01);              /* CTC mode */
    TCCR0B = (1 << CS01) | (1 << CS00); /* Prescaler 64 */
    OCR0A  = 249;
    TIMSK0 |= (1 << OCIE0A);            /* Bật ngắt so sánh kênh A */

    /* Cấu hình Timer2: Chế độ CTC, Prescaler 8, ngắt 50 kHz */
    TCCR2A = (1 << WGM21);              /* CTC mode */
    TCCR2B = (1 << CS21);               /* Prescaler 8 */
    OCR2A  = 39;
    TIMSK2 |= (1 << OCIE2A);            /* Bật ngắt so sánh kênh A */
}

/* Ngắt Timer0: 1 ms hệ thống, đánh cờ kích hoạt Tầng 2 mỗi chu kỳ điều khiển */
ISR(TIMER0_COMPA_vect) {
    s_system_ms++;
    s_tick_counter_4ms++;
    if (s_tick_counter_4ms >= CONTROL_LOOP_MS) {
        s_tick_counter_4ms = 0;
        s_flag_control_4ms = true;
    }
}

/* Ngắt Timer2: Tầng 1 sinh xung bước */
ISR(TIMER2_COMPA_vect) {
    motor_isr_step();
}

uint32_t timer_get_ms(void) {
    uint32_t ms;
    uint8_t sreg = SREG;
    cli(); /* Cấm ngắt ngắn gọn vài chu kỳ lệnh asm */
    ms = s_system_ms;
    SREG = sreg;
    return ms;
}

bool timer_check_control_flag(void) {
    if (s_flag_control_4ms) {
        s_flag_control_4ms = false;
        return true;
    }
    return false;
}

#ifndef I2C_H_
#define I2C_H_

#include <stdint.h>
#include <stdbool.h>

/* Khởi tạo module TWI phần cứng ở 400 kHz */
void i2c_init(void);

/* Phát điều kiện START và gửi địa chỉ thiết bị + hướng R/W */
bool i2c_start(uint8_t address);

/* Phát điều kiện STOP */
void i2c_stop(void);

/* Gửi một byte dữ liệu */
bool i2c_write(uint8_t data);

/* Đọc một byte dữ liệu và trả ACK */
bool i2c_read_ack(uint8_t *data);

/* Đọc một byte dữ liệu và trả NACK */
bool i2c_read_nack(uint8_t *data);

/* Đọc một khối dữ liệu từ thanh ghi thiết bị */
bool i2c_read_bytes(uint8_t dev_addr, uint8_t reg_addr, uint8_t *buffer, uint8_t length);

/* Ghi một byte vào thanh ghi thiết bị */
bool i2c_write_byte(uint8_t dev_addr, uint8_t reg_addr, uint8_t data);

#endif /* I2C_H_ */

#include "i2c.h"
#include "config.h"
#include <avr/io.h>

void i2c_init(void) {
    /* TWBR = 12 với F_CPU = 16 MHz và Prescaler = 1 tạo xung SCL 400 kHz */
    TWSR = 0x00;
    TWBR = 12;
    TWCR = (1 << TWEN);
}

static bool i2c_wait_twint(void) {
    uint16_t timeout = I2C_TIMEOUT_CYCLES;
    while (!(TWCR & (1 << TWINT))) {
        if (--timeout == 0) {
            return false; /* Hết thời gian chờ - tránh treo CPU */
        }
    }
    return true;
}

bool i2c_start(uint8_t address) {
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
    if (!i2c_wait_twint()) {
        return false;
    }

    TWDR = address;
    TWCR = (1 << TWINT) | (1 << TWEN);
    return i2c_wait_twint();
}

void i2c_stop(void) {
    TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
}

bool i2c_write(uint8_t data) {
    TWDR = data;
    TWCR = (1 << TWINT) | (1 << TWEN);
    return i2c_wait_twint();
}

bool i2c_read_ack(uint8_t *data) {
    TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWEA);
    if (!i2c_wait_twint()) {
        return false;
    }
    *data = TWDR;
    return true;
}

bool i2c_read_nack(uint8_t *data) {
    TWCR = (1 << TWINT) | (1 << TWEN);
    if (!i2c_wait_twint()) {
        return false;
    }
    *data = TWDR;
    return true;
}

bool i2c_write_byte(uint8_t dev_addr, uint8_t reg_addr, uint8_t data) {
    if (!i2c_start((dev_addr << 1) | 0)) {
        i2c_stop();
        return false;
    }
    if (!i2c_write(reg_addr)) {
        i2c_stop();
        return false;
    }
    if (!i2c_write(data)) {
        i2c_stop();
        return false;
    }
    i2c_stop();
    return true;
}

bool i2c_read_bytes(uint8_t dev_addr, uint8_t reg_addr, uint8_t *buffer, uint8_t length) {
    if (!i2c_start((dev_addr << 1) | 0)) {
        i2c_stop();
        return false;
    }
    if (!i2c_write(reg_addr)) {
        i2c_stop();
        return false;
    }
    if (!i2c_start((dev_addr << 1) | 1)) {
        i2c_stop();
        return false;
    }
    for (uint8_t i = 0; i < length; i++) {
        if (i == (length - 1)) {
            if (!i2c_read_nack(&buffer[i])) {
                i2c_stop();
                return false;
            }
        } else {
            if (!i2c_read_ack(&buffer[i])) {
                i2c_stop();
                return false;
            }
        }
    }
    i2c_stop();
    return true;
}

#ifndef MPU6050_H_
#define MPU6050_H_

#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} mpu6050_raw_data_t;

typedef struct {
    float accel_x_g;
    float accel_y_g;
    float accel_z_g;
    float gyro_x_dps;
    float gyro_y_dps;
    float gyro_z_dps;
} mpu6050_data_t;

/* Khởi tạo cảm biến MPU6050 qua I2C */
bool mpu6050_init(void);

/* Đọc toàn bộ 6 trục cảm biến thô */
bool mpu6050_read_raw(mpu6050_raw_data_t *raw);

/* Quy trình tự động hiệu chuẩn offset tĩnh con quay (FR-02) */
bool mpu6050_calibrate_gyro(void);

/* Đọc dữ liệu đã trừ offset hiệu chuẩn và đổi sang đơn vị vật lý */
bool mpu6050_read_scaled(mpu6050_data_t *data);

#endif /* MPU6050_H_ */

#include "mpu6050.h"
#include "config.h"
#include "i2c.h"

#define REG_SMPLRT_DIV    0x19
#define REG_CONFIG        0x1A
#define REG_GYRO_CONFIG   0x1B
#define REG_ACCEL_CONFIG  0x1C
#define REG_ACCEL_XOUT_H  0x3B
#define REG_PWR_MGMT_1    0x6B

#define ACCEL_SCALE_FACTOR 16384.0f
#define GYRO_SCALE_FACTOR  131.0f

static float s_gyro_bias_x = 0.0f;
static float s_gyro_bias_y = 0.0f;
static float s_gyro_bias_z = 0.0f;

bool mpu6050_init(void) {
    /* Đánh thức MPU6050 bằng cách xoá bit SLEEP trong thanh ghi PWR_MGMT_1 */
    if (!i2c_write_byte(MPU6050_ADDR, REG_PWR_MGMT_1, 0x00)) {
        return false;
    }
    /* Đặt bộ lọc thông thấp số DLPF (băng thông khoảng 42 Hz) */
    if (!i2c_write_byte(MPU6050_ADDR, REG_CONFIG, 0x03)) {
        return false;
    }
    /* Đặt thang đo con quay +/- 250 độ/giây */
    if (!i2c_write_byte(MPU6050_ADDR, REG_GYRO_CONFIG, 0x00)) {
        return false;
    }
    /* Đặt thang đo gia tốc +/- 2g */
    if (!i2c_write_byte(MPU6050_ADDR, REG_ACCEL_CONFIG, 0x00)) {
        return false;
    }
    return true;
}

bool mpu6050_read_raw(mpu6050_raw_data_t *raw) {
    uint8_t buf[14];
    if (!i2c_read_bytes(MPU6050_ADDR, REG_ACCEL_XOUT_H, buf, 14)) {
        return false;
    }

    raw->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw->accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    /* Bỏ qua nhiệt độ buf[6], buf[7] */
    raw->gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    raw->gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    raw->gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return true;
}

bool mpu6050_calibrate_gyro(void) {
    int32_t sum_gx = 0;
    int32_t sum_gy = 0;
    int32_t sum_gz = 0;
    mpu6050_raw_data_t raw;

    for (uint16_t i = 0; i < CALIB_SAMPLES; i++) {
        if (!mpu6050_read_raw(&raw)) {
            return false;
        }
        sum_gx += raw.gyro_x;
        sum_gy += raw.gyro_y;
        sum_gz += raw.gyro_z;
    }

    s_gyro_bias_x = (float)sum_gx / ((float)CALIB_SAMPLES * GYRO_SCALE_FACTOR);
    s_gyro_bias_y = (float)sum_gy / ((float)CALIB_SAMPLES * GYRO_SCALE_FACTOR);
    s_gyro_bias_z = (float)sum_gz / ((float)CALIB_SAMPLES * GYRO_SCALE_FACTOR);

    return true;
}

bool mpu6050_read_scaled(mpu6050_data_t *data) {
    mpu6050_raw_data_t raw;
    if (!mpu6050_read_raw(&raw)) {
        return false;
    }

    data->accel_x_g = (float)raw.accel_x / ACCEL_SCALE_FACTOR;
    data->accel_y_g = (float)raw.accel_y / ACCEL_SCALE_FACTOR;
    data->accel_z_g = (float)raw.accel_z / ACCEL_SCALE_FACTOR;

    data->gyro_x_dps = ((float)raw.gyro_x / GYRO_SCALE_FACTOR) - s_gyro_bias_x;
    data->gyro_y_dps = ((float)raw.gyro_y / GYRO_SCALE_FACTOR) - s_gyro_bias_y;
    data->gyro_z_dps = ((float)raw.gyro_z / GYRO_SCALE_FACTOR) - s_gyro_bias_z;

    return true;
}

