#ifndef FILTER_H_
#define FILTER_H_

typedef struct {
    float angle;      /* Góc nghiêng ước lượng hiện tại (độ) */
    float gyro_rate;  /* Tốc độ góc (độ/giây) */
    float alpha;      /* Trọng số bộ lọc bù (anh cho, chưa có tài liệu) */
    float dt;         /* Khoảng thời gian lấy mẫu (giây) */
} comp_filter_t;

/* Khởi tạo bộ lọc bù với chu kỳ lấy mẫu dt và hệ số alpha */
void filter_init(comp_filter_t *f, float alpha, float dt);

/* Cập nhật bộ lọc bù với dữ liệu gia tốc và con quay */
float filter_update(comp_filter_t *f, float accel_angle, float gyro_rate);

#endif /* FILTER_H_ */

#include "filter.h"

void filter_init(comp_filter_t *f, float alpha, float dt) {
    f->angle     = 0.0f;
    f->gyro_rate = 0.0f;
    f->alpha     = alpha;
    f->dt        = dt;
}

float filter_update(comp_filter_t *f, float accel_angle, float gyro_rate) {
    f->gyro_rate = gyro_rate;
    /* Tích hợp con quay và bù lại bằng góc đo từ gia tốc kế */
    f->angle = f->alpha * (f->angle + gyro_rate * f->dt) + (1.0f - f->alpha) * accel_angle;
    return f->angle;
}

#ifndef PID_H_
#define PID_H_

typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float integral_max;
    float out_max;
} pid_controller_t;

/* Khởi tạo thông số bộ điều khiển PID */
void pid_init(pid_controller_t *pid, float kp, float ki, float kd, float integral_max, float out_max);

/* Cập nhật tính toán PID với sai số và khoảng thời gian dt */
float pid_calculate(pid_controller_t *pid, float setpoint, float current_val, float dt);

/* Xoá bộ tích phân khi dừng động cơ hoặc chuyển trạng thái */
void pid_reset(pid_controller_t *pid);

#endif /* PID_H_ */

#include "pid.h"

void pid_init(pid_controller_t *pid, float kp, float ki, float kd, float integral_max, float out_max) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_max = integral_max;
    pid->out_max = out_max;
}

float pid_calculate(pid_controller_t *pid, float setpoint, float current_val, float dt) {
    float error = setpoint - current_val;

    /* Thành phần vi phân */
    float derivative = 0.0f;
    if (dt > 0.0f) {
        derivative = (error - pid->prev_error) / dt;
    }
    pid->prev_error = error;

    /* Thành phần tích phân có kẹp giới hạn chống windup */
    pid->integral += error * dt;
    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < -pid->integral_max) {
        pid->integral = -pid->integral_max;
    }

    /* Tính đầu ra */
    float output = (pid->kp * error) + (pid->ki * pid->integral) + (pid->kd * derivative);

    /* Kẹp giới hạn đầu ra bão hòa */
    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < -pid->out_max) {
        output = -pid->out_max;
    }

    return output;
}

void pid_reset(pid_controller_t *pid) {
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
}

#ifndef MOTOR_H_
#define MOTOR_H_

#include <stdint.h>
#include <stdbool.h>

/* Khởi tạo chân I/O điều khiển driver động cơ bước A4988 */
void motor_init(void);

/* Cài đặt tốc độ bước cho hai bánh xe (xung/giây) */
void motor_set_speed(int16_t speed_left, int16_t speed_right);

/* Dừng hoàn toàn việc phát xung bước (Chân EN nối cứng GND nên dừng bằng cách tắt xung STEP) */
void motor_stop(void);

/* Bật cho phép phát xung bước */
void motor_enable(void);

/* Hàm thực thi trong ISR ngắt Timer2 50 kHz (Tầng 1) */
void motor_isr_step(void);

#endif /* MOTOR_H_ */

#include "motor.h"
#include "config.h"
#include <stdlib.h>

static volatile bool s_motor_active = false;
static volatile int16_t s_speed_left = 0;
static volatile int16_t s_speed_right = 0;

static uint32_t s_accum_left = 0;
static uint32_t s_accum_right = 0;

void motor_init(void) {
    /* Cấu hình các chân điều khiển động cơ bước là OUTPUT */
    MOTOR_L_STEP_DDR |= (1 << MOTOR_L_STEP_PIN);
    MOTOR_L_DIR_DDR  |= (1 << MOTOR_L_DIR_PIN);
    MOTOR_R_STEP_DDR |= (1 << MOTOR_R_STEP_PIN);
    MOTOR_R_DIR_DDR  |= (1 << MOTOR_R_DIR_PIN);

    motor_stop();
}

void motor_set_speed(int16_t speed_left, int16_t speed_right) {
    s_speed_left = speed_left;
    s_speed_right = speed_right;

    /* Cập nhật hướng quay DIR */
    if (speed_left >= 0) {
        MOTOR_L_DIR_PORT |= (1 << MOTOR_L_DIR_PIN);
    } else {
        MOTOR_L_DIR_PORT &= ~(1 << MOTOR_L_DIR_PIN);
    }

    if (speed_right >= 0) {
        MOTOR_R_DIR_PORT |= (1 << MOTOR_R_DIR_PIN);
    } else {
        MOTOR_R_DIR_PORT &= ~(1 << MOTOR_R_DIR_PIN);
    }
}

void motor_stop(void) {
    s_motor_active = false;
    s_speed_left = 0;
    s_speed_right = 0;
    s_accum_left = 0;
    s_accum_right = 0;

    /* Kéo xung STEP xuống mức thấp để ngừng kích hoạt bước */
    /* Lưu ý: Chân EN nối cứng GND nên dừng động cơ bằng cách ngắt xung STEP */
    MOTOR_L_STEP_PORT &= ~(1 << MOTOR_L_STEP_PIN);
    MOTOR_R_STEP_PORT &= ~(1 << MOTOR_R_STEP_PIN);
}

void motor_enable(void) {
    s_motor_active = true;
}

/* Hàm chạy trong ISR Timer2 ngắt 50 kHz (Tầng 1) */
void motor_isr_step(void) {
    if (!s_motor_active) {
        MOTOR_L_STEP_PORT &= ~(1 << MOTOR_L_STEP_PIN);
        MOTOR_R_STEP_PORT &= ~(1 << MOTOR_R_STEP_PIN);
        return;
    }

    /* Thuật toán DDA tích luỹ bước động cơ trái */
    uint16_t mag_l = (uint16_t)abs(s_speed_left);
    s_accum_left += mag_l;
    if (s_accum_left >= TIMER2_FREQ_HZ) {
        s_accum_left -= TIMER2_FREQ_HZ;
        MOTOR_L_STEP_PORT |= (1 << MOTOR_L_STEP_PIN);
    } else {
        MOTOR_L_STEP_PORT &= ~(1 << MOTOR_L_STEP_PIN);
    }

    /* Thuật toán DDA tích luỹ bước động cơ phải */
    uint16_t mag_r = (uint16_t)abs(s_speed_right);
    s_accum_right += mag_r;
    if (s_accum_right >= TIMER2_FREQ_HZ) {
        s_accum_right -= TIMER2_FREQ_HZ;
        MOTOR_R_STEP_PORT |= (1 << MOTOR_R_STEP_PIN);
    } else {
        MOTOR_R_STEP_PORT &= ~(1 << MOTOR_R_STEP_PIN);
    }
}

#ifndef FSM_H_
#define FSM_H_

#include <stdint.h>
#include <stdbool.h>

typedef enum {
    STATE_INIT = 0,
    STATE_CALIBRATING,
    STATE_READY,
    STATE_BALANCING,
    STATE_FALLEN,
    STATE_STOPPED
} robot_state_t;

/* Khởi tạo máy trạng thái và các chân ngoại vi nút bấm/còi */
void fsm_init(void);

/* Cập nhật tác vụ nền Tầng 3: quét nút nhấn D12, quản lý còi D10 */
void fsm_update_background(void);

/* Cập nhật vòng lặp điều khiển Tầng 2 (chu kỳ 4 ms) */
void fsm_update_control_4ms(void);

/* Lấy trạng thái hiện tại của robot */
robot_state_t fsm_get_state(void);

#endif /* FSM_H_ */

#include "fsm.h"
#include "config.h"
#include "timer.h"
#include "mpu6050.h"
#include "filter.h"
#include "pid.h"
#include "motor.h"
#include <math.h>

#define RAD_TO_DEG_FACTOR 57.29578f /* (anh cho, chưa có tài liệu) */

static robot_state_t s_state = STATE_INIT;
static comp_filter_t s_filter;
static pid_controller_t s_pid;

/* Quản lý nút nhấn phi chặn */
static bool s_prev_btn_state = true;
static uint32_t s_last_btn_time = 0;

/* Quản lý còi phi chặn */
static uint32_t s_buzzer_off_time = 0;

static void buzzer_on_ms(uint16_t duration_ms) {
    BUZZER_PORT |= (1 << BUZZER_PIN);
    s_buzzer_off_time = timer_get_ms() + duration_ms;
}

void fsm_init(void) {
    /* Cấu hình chân Buzzer D10 là OUTPUT, ban đầu tắt */
    BUZZER_DDR |= (1 << BUZZER_PIN);
    BUZZER_PORT &= ~(1 << BUZZER_PIN);

    /* Cấu hình chân Button D12 là INPUT có điện trở kéo lên PULL-UP */
    BUTTON_DDR &= ~(1 << BUTTON_PIN);
    BUTTON_PORT |= (1 << BUTTON_PIN);

    /* Khởi tạo bộ lọc bù: alpha = 0.98, dt = 4 ms */
    filter_init(&s_filter, 0.98f, CONTROL_LOOP_DT);

    /* Khởi tạo PID: Kp = 15.0, Ki = 0.8, Kd = 0.5, MaxI = 100.0, MaxOut = 2000.0 */
    pid_init(&s_pid, 15.0f, 0.8f, 0.5f, 100.0f, 2000.0f);

    s_state = STATE_INIT;
}

robot_state_t fsm_get_state(void) {
    return s_state;
}

void fsm_update_background(void) {
    uint32_t now = timer_get_ms();

    /* Tự động tắt còi phi chặn khi hết thời gian */
    if (s_buzzer_off_time > 0 && now >= s_buzzer_off_time) {
        BUZZER_PORT &= ~(1 << BUZZER_PIN);
        s_buzzer_off_time = 0;
    }

    /* Đọc nút nhấn D12 chống rung phi chặn */
    bool current_btn = (BUTTON_PINREG & (1 << BUTTON_PIN)) ? true : false;
    if (s_prev_btn_state && !current_btn) {
        /* Bắt sườn xuống nút bấm */
        if (now - s_last_btn_time > 200) {
            s_last_btn_time = now;
            /* Xử lý bấm nút (FR-03) */
            if (s_state == STATE_BALANCING || s_state == STATE_READY) {
                /* Bấm nút khi đang chạy hoặc sẵn sàng -> Dừng hẳn (FR-03) */
                s_state = STATE_STOPPED;
                motor_stop();
                pid_reset(&s_pid);
                buzzer_on_ms(100);
            } else if (s_state == STATE_STOPPED || s_state == STATE_FALLEN) {
                /* Bấm nút khi đang dừng/ngã -> Đưa về sẵn sàng (FR-03) */
                s_state = STATE_READY;
                motor_stop();
                pid_reset(&s_pid);
                buzzer_on_ms(50);
            }
        }
    }
    s_prev_btn_state = current_btn;

    /* Xử lý khởi tạo và hiệu chuẩn ở trạng thái INIT */
    if (s_state == STATE_INIT) {
        buzzer_on_ms(50); /* Báo hiệu đang khởi động (FR-01) */
        s_state = STATE_CALIBRATING;
        if (mpu6050_calibrate_gyro()) {
            /* Tự hiệu chuẩn thành công (FR-02) -> chuyển sang READY */
            s_state = STATE_READY;
            buzzer_on_ms(200); /* Còi kêu báo sẵn sàng (FR-01) */
        } else {
            /* Cảm biến lỗi */
            s_state = STATE_STOPPED;
        }
    }
}

void fsm_update_control_4ms(void) {
    mpu6050_data_t imu;
    if (!mpu6050_read_scaled(&imu)) {
        return;
    }

    /* Tính góc nghiêng pitch từ gia tốc kế */
    float accel_pitch = atan2f(-imu.accel_x_g, imu.accel_z_g) * RAD_TO_DEG_FACTOR;

    /* Cập nhật bộ lọc bù với tốc độ con quay trục Y */
    float pitch = filter_update(&s_filter, accel_pitch, imu.gyro_y_dps);

    switch (s_state) {
        case STATE_READY:
            /* Tự động kích hoạt khi đi qua điểm thăng bằng (FR-04) */
            if (fabsf(pitch) < (float)ANGLE_ACTIVE_DEG) {
                s_state = STATE_BALANCING;
                pid_reset(&s_pid);
                motor_enable();
            }
            break;

        case STATE_BALANCING:
            /* Kiểm tra điều kiện ngã xe (FR-05) */
            if (fabsf(pitch) > (float)ANGLE_FALL_LIMIT_DEG) {
                s_state = STATE_FALLEN;
                motor_stop();
                pid_reset(&s_pid);
                buzzer_on_ms(300); /* Còi báo ngã */
            } else {
                /* Tính toán PID cân bằng */
                float speed_out = pid_calculate(&s_pid, 0.0f, pitch, CONTROL_LOOP_DT);
                int16_t motor_spd = (int16_t)speed_out;
                motor_set_speed(motor_spd, motor_spd);
            }
            break;

        case STATE_FALLEN:
        case STATE_STOPPED:
        default:
            motor_stop();
            break;
    }
}

#include "config.h"
#include "timer.h"
#include "i2c.h"
#include "mpu6050.h"
#include "motor.h"
#include "fsm.h"
#include <avr/interrupt.h>

int main(void) {
    /* 1. Khởi tạo giao tiếp I2C phần cứng TWI */
    i2c_init();

    /* 2. Khởi tạo cảm biến con quay quán tính MPU6050 */
    mpu6050_init();

    /* 3. Khởi tạo chân I/O điều khiển động cơ bước A4988 */
    motor_init();

    /* 4. Khởi tạo máy trạng thái và chân nút nhấn/còi */
    fsm_init();

    /* 5. Khởi tạo hệ thống Timer0 (1 kHz) và Timer2 (50 kHz) */
    timer_init();

    /* 6. Cho phép ngắt toàn cục */
    sei();

    /* Vòng lặp chính kết hợp Tầng 2 và Tầng 3 */
    while (1) {
        /* Tầng 2: Vòng lặp điều khiển thời gian thực chu kỳ 4 ms (250 Hz) */
        if (timer_check_control_flag()) {
            fsm_update_control_4ms();
        }

        /* Tầng 3: Tác vụ nền phi chặn (nút bấm, còi, kiểm tra trạng thái) */
        fsm_update_background();

        /* LƯU Ý BẢO MẬT THỜI GIAN THỰC (NFR-02):
         * - Không sử dụng _delay_ms() gây chặn CPU.
         * - Tuyệt đối không cấm ngắt quá 1,5 µs.
         * - Không truyền chuỗi LED WS2812 khi hệ thống đang vận hành cân bằng.
         */
    }

    return 0;
}

