void i2c_stop(void) {
    TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
    uint16_t timeout = I2C_TIMEOUT_CYCLES;
    while (TWCR & (1 << TWSTO)) {
        if (--timeout == 0) {
            break; /* Hết thời gian chờ - tránh treo CPU */
        }
    }
}

