/* Báo lỗi cảm biến quán tính (MPU6050) và kích hoạt mã bíp cảnh báo */
void fsm_notify_sensor_error(void);

/* Kiểm tra xem hệ thống có đang ở trạng thái lỗi cảm biến không */
