                    buzzer_on_ms(200);
                } else {
                    /* Tự hiệu chuẩn thành công -> chuyển sang STOPPED CHỜ BẤM NÚT */
                    s_state = STATE_STOPPED;
                    buzzer_on_ms(200);
                }
            }
        }
    }
}

