    uint8_t accel_cfg_verify = 0;
    if (!i2c_read_bytes(MPU6050_ADDR, REG_ACCEL_CONFIG, &accel_cfg_verify, 1) || accel_cfg_verify != 0x08) {
        return false;
    }

    return true;
}

