        return false;
    }
    if (who_am_i != 0x68 && who_am_i != 0x69 && who_am_i != 0x70) {
        snprintf(s_mpu_init_diag, sizeof(s_mpu_init_diag), "WHO_AM_I mismatch: 0x%02X (exp 0x68)", who_am_i);
